const body = $json.body ?? $json;
const text = `${body.message || ''} ${body.notes || ''}`.toLowerCase();
let intent = 'diagnostico';
let service = body.service || 'Não classificado';
let nextQuestion = 'Qual resultado você quer alcançar com este projeto?';
if (/site|landing|página/.test(text)) { service='Site ou landing page'; nextQuestion='Qual é o principal objetivo da página?'; }
if (/chatbot|atendimento|whatsapp/.test(text)) { service='Chatbot'; nextQuestion='Quais dúvidas mais se repetem no atendimento?'; }
if (/automação|processo|relatório|erp/.test(text)) { service='Automação empresarial'; nextQuestion='Qual tarefa manual mais consome tempo hoje?'; }
if (/preço|valor|orçamento/.test(text)) intent='orcamento';
if (/humano|pessoa|arthur/.test(text)) intent='handoff_humano';
return [{json:{intent,service,nextQuestion,requiresHuman:intent==='handoff_humano',confidence:0.82}}];
